/* From Uiverse.io by nanda248  - Tags: card, playing card, stack of cards, gold card */
.__UIV_SCOPE__ .main {
  position: relative;
}

/* card styles */
.__UIV_SCOPE__ .card {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: 1fr 1fr 1fr;
  grid-auto-flow: row;
  grid-template-areas:
    "i1 . ."
    ". center ."
    ". . i2";
  width: 12em;
  height: 18em;
  border-radius: 4px;
  background: #ffd700;
  transition: 0.5s;
  z-index: 20;
}

.__UIV_SCOPE__ .bg-card-1 {
  background-color: #daa520;
  position: absolute;
  top: 0;
  width: 12em;
  height: 18em;
  border-radius: 4px;
  transition: 0.5s;
  z-index: 8;
}

.__UIV_SCOPE__ .bg-card-2 {
  background-color: #b8860b;
  position: absolute;
  top: 0;
  width: 12em;
  height: 18em;
  border-radius: 4px;
  transition: 0.5s;
  z-index: 4;
}

/* glider animation */
.__UIV_SCOPE__ .card:before {
  content: "";
  position: absolute;
  height: 130%;
  width: 0.6em;
  background-color: aliceblue;
  opacity: 0.3;
  animation: glider 1.8s infinite linear;
  animation-delay: 0.05s;
}

.__UIV_SCOPE__ .card:after {
  content: "";
  position: absolute;
  height: 130%;
  width: 0.4em;
  background-color: aliceblue;
  opacity: 0.2;
  animation: glider 1.8s infinite linear;
}

@keyframes glider {
  0% {
    transform: rotate(45deg) translate(-140px, -140px);
  }

  100% {
    transform: rotate(45deg) translate(220px, -40px);
  }
}

/* icon styles */
.__UIV_SCOPE__ .i1,
.__UIV_SCOPE__ .i2 svg {
  width: 1.5em;
  fill: #ff3131;
}

.__UIV_SCOPE__ .i1 {
  grid-area: i1;
  justify-self: flex-start;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  margin: 0.2em 0.4em;
}

.__UIV_SCOPE__ .i2 {
  grid-area: i2;
  justify-self: flex-end;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  margin: 0.2em 0.4em;
  transform: rotate(180deg);
}

.__UIV_SCOPE__ .corner-text {
  color: #ff3131;
  font-weight: bold;
  font-size: 1.2em;
}

.__UIV_SCOPE__ .center-shape {
  grid-area: center;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .center-shape svg {
  width: 4em;
  fill: #ff3131;
}

/* hover effects */
.__UIV_SCOPE__ .card:hover {
  box-shadow: #ffd700 0px 7px 29px 0px;
  cursor: pointer;
}

.__UIV_SCOPE__ .card:hover:after,
.__UIV_SCOPE__ .card:hover:before {
  visibility: hidden;
}

.__UIV_SCOPE__ .card:hover svg,
.__UIV_SCOPE__ .card:hover span {
  animation: color-change 1s ease-in-out;
  animation-fill-mode: forwards;
}

@keyframes color-change {
  from {
    fill: #ff3131;
    color: #ff3131;
  }

  to {
    fill: #e34234;
    color: #e34234;
  }
}

/* hover fan out effects */
.__UIV_SCOPE__ .card:active {
  transform: rotate(10deg);
  transform-origin: bottom left;
  box-shadow: none;
}

.__UIV_SCOPE__ .card:active + .bg-card-1 {
  transform: rotate(5deg);
  transform-origin: bottom left;
}
